mapper.select:
SELECT INTRODUCTION_NO, USER_ID, INTRODUCTION_NAME, INTRODUCTION_CONTENT 
  FROM INTRODUCTION
 WHERE INTRODUCTION_NO = #{introductionNo}
   AND USER_ID = #{userId}

mapper.insert:
INSERT INTO INTRODUCTION (

		SELECT
		    'INT'||
		    LPAD(NVL(TO_NUMBER(SUBSTR(MAX(INTRODUCTION_NO), LENGTH('ABC')+1)),0) + 1, 7, '0')
		FROM INTRODUCTION

	INTRODUCTION_NO
	, USER_ID
	, INTRODUCTION_NAME
	, INTRODUCTION_CONTENT
) VALUES (
	#{introductionNo}
	, #{userId}
	, #{introductionName}
	, #{introductionContent}
)

mapper.update:
UPDATE INTRODUCTION 
   SET INTRODUCTION_NAME = #{introductionName}
       , INTRODUCTION_CONTENT = #{introductionContent}
 WHERE INTRODUCTION_NO = #{introductionNo}
   AND USER_ID = #{userId}

mapper.delete:
DELETE FROM INTRODUCTION 
 WHERE INTRODUCTION_NO = #{introductionNo}
   AND USER_ID = #{userId}
